  "package": "@astryxdesign/core",
  "data": {
    "template": "TabMenuShowcase",
    "description": "TabMenu is an overflow menu within a TabList that groups additional tab options into a dropdown, showing the selected option's label as the trigger text.",
    "type": "block",
    "components": [
      "Tab",
      "TabList",
      "TabMenu"
    ],
    "source": "// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {useState} from 'react';\nimport {TabList, Tab, TabMenu} from '@astryxdesign/core/TabList';\n\nexport default function TabMenuShowcase() {\n  const [value, setValue] = useState('settings');\n  return (\n    <TabList value={value} onChange={setValue}>\n      <Tab value=\"overview\" label=\"Overview\" />\n      <Tab value=\"activity\" label=\"Activity\" />\n      <TabMenu\n        label=\"More\"\n        options={[\n          {value: 'settings', label: 'Settings'},\n          {value: 'integrations', label: 'Integrations'},\n          {value: 'billing', label: 'Billing'},\n        ]}\n      />\n    </TabList>\n  );\n}\n",
    "demoMediaReplaced": 0,
    "demoContentReplaced": 0
  },
